/* tslint:disable */
/* eslint-disable */
/**
 * The different types of addresses.
 */

export type AddressType = "p2pkh" | "p2sh" | "p2wpkh" | "p2wsh" | "p2tr";
/**
 * A set of denominations in which amounts can be expressed.
 */

export type Denomination = "BTC" | "cBTC" | "mBTC" | "uBTC" | "nBTC" | "pBTC" | "bits" | "satoshi" | "msat";
/**
 * Types of keychains
 */

export type KeychainKind = "external" | "internal";
/**
 * The cryptocurrency network to act on.
 */

export type Network = "bitcoin" | "testnet" | "testnet4" | "signet" | "regtest";
/**
 * What kind of network we are on.
 */

export type NetworkKind = "main" | "test";
/**
 * The kind of wallet event.
 */

export type WalletEventKind = "chain_tip_changed" | "tx_confirmed" | "tx_unconfirmed" | "tx_replaced" | "tx_dropped";

/**
 * A Bitcoin address.
 */
export class Address {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    clone(): Address;
    /**
     * Constructs an [`Address`] from an output script (`scriptPubkey`).
     */
    static from_script(script_buf: ScriptBuf, network: Network): Address;
    static from_string(address_str: string, network: Network): Address;
    toString(): string;
    readonly script_pubkey: ScriptBuf;
}

/**
 * A derived address and the index it was found at.
 */
export class AddressInfo {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    clone(): AddressInfo;
    /**
     * Address
     */
    readonly address: Address;
    /**
     * Gets the address type of the address.
     *
     * # Returns
     *
     * None if unknown, non-standard or related to the future witness version.
     */
    readonly address_type: AddressType | undefined;
    /**
     * Child index of this address
     */
    readonly index: number;
    /**
     * Type of keychain
     */
    readonly keychain: KeychainKind;
}

/**
 * Amount
 *
 * The [Amount] type can be used to express Bitcoin amounts that support
 * arithmetic and conversion to various denominations.
 */
export class Amount {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    static from_btc(btc: number): Amount;
    static from_sat(satoshi: bigint): Amount;
    /**
     * Check whether or not a value is below dust limit
     * for a given script
     */
    is_dust(script: ScriptBuf): boolean;
    /**
     * Express this [`Amount`] as a floating-point value in Bitcoin.
     *
     * Please be aware of the risk of using floating-point numbers.
     */
    to_btc(): number;
    /**
     * Express this [Amount] as a floating-point value in the given denomination.
     *
     * Please be aware of the risk of using floating-point numbers.
     */
    to_float_in(denom: Denomination): number;
    /**
     * Gets the number of satoshis in this [`Amount`].
     */
    to_sat(): bigint;
}

/**
 * Balance, differentiated into various categories.
 */
export class Balance {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    /**
     * Confirmed and immediately spendable balance
     */
    readonly confirmed: Amount;
    /**
     * All coinbase outputs not yet matured
     */
    readonly immature: Amount;
    /**
     * Get the whole balance visible to the wallet.
     */
    readonly total: Amount;
    /**
     * Unconfirmed UTXOs generated by a wallet tx
     */
    readonly trusted_pending: Amount;
    /**
     * Get sum of trusted_pending and confirmed coins.
     *
     * This is the balance you can spend right now that shouldn't get cancelled via another party
     * double spending it.
     */
    readonly trusted_spendable: Amount;
    /**
     * Unconfirmed UTXOs received from an external wallet
     */
    readonly untrusted_pending: Amount;
}

export class BdkError {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    readonly code: BdkErrorCode;
    readonly data: any;
    readonly message: string;
}

export enum BdkErrorCode {
    /**
     * ------- Transaction creation errors -------
     * There was a problem with the descriptors passed in
     */
    Descriptor = 0,
    /**
     * There was a problem while extracting and manipulating policies
     */
    Policy = 1,
    /**
     * Spending policy is not compatible with this [`KeychainKind`]
     */
    SpendingPolicyRequired = 2,
    /**
     * Requested invalid transaction version '0'
     */
    Version0 = 3,
    /**
     * Requested transaction version `1`, but at least `2` is needed to use OP_CSV
     */
    Version1Csv = 4,
    /**
     * Requested `LockTime` is less than is required to spend from this script
     */
    LockTime = 5,
    /**
     * Cannot enable RBF with `Sequence` given a required OP_CSV
     */
    RbfSequenceCsv = 6,
    /**
     * When bumping a tx the absolute fee requested is lower than replaced tx absolute fee
     */
    FeeTooLow = 7,
    /**
     * When bumping a tx the fee rate requested is lower than required
     */
    FeeRateTooLow = 8,
    /**
     * `manually_selected_only` option is selected but no utxo has been passed
     */
    NoUtxosSelected = 9,
    /**
     * Output created is under the dust limit, 546 satoshis
     */
    OutputBelowDustLimit = 10,
    /**
     * Wallet's UTXO set is not enough to cover recipient's requested plus fee.
     */
    InsufficientFunds = 11,
    /**
     * Cannot build a tx without recipients
     */
    NoRecipients = 12,
    /**
     * Partially signed bitcoin transaction error
     */
    Psbt = 13,
    /**
     * In order to use the [`TxBuilder::add_global_xpubs`] option every extended
     * key in the descriptor must either be a master key itself (having depth = 0) or have an
     * explicit origin provided
     *
     * [`TxBuilder::add_global_xpubs`]: crate::wallet::tx_builder::TxBuilder::add_global_xpubs
     */
    MissingKeyOrigin = 14,
    /**
     * Happens when trying to spend an UTXO that is not in the internal database
     */
    UnknownUtxo = 15,
    /**
     * Missing non_witness_utxo on foreign utxo for given `OutPoint`
     */
    MissingNonWitnessUtxo = 16,
    /**
     * Miniscript PSBT error
     */
    MiniscriptPsbt = 17,
    /**
     * ------- Fee bump errors -------
     * Transaction not found in the internal database
     */
    TransactionNotFound = 18,
    /**
     * Transaction is already confirmed, cannot fee-bump
     */
    TransactionConfirmed = 19,
    /**
     * Transaction does not signal RBF (sequence >= 0xFFFFFFFE)
     */
    IrreplaceableTransaction = 20,
    /**
     * Fee rate data is unavailable
     */
    FeeRateUnavailable = 21,
    /**
     * Input references an invalid output index
     */
    InvalidOutputIndex = 22,
    /**
     * ------- Address errors -------
     * Base58 error.
     */
    Base58 = 23,
    /**
     * Bech32 segwit decoding error.
     */
    Bech32 = 24,
    /**
     * A witness version conversion/parsing error.
     */
    WitnessVersion = 25,
    /**
     * A witness program error.
     */
    WitnessProgram = 26,
    /**
     * Tried to parse an unknown HRP.
     */
    UnknownHrp = 27,
    /**
     * Legacy address is too long.
     */
    LegacyAddressTooLong = 28,
    /**
     * Invalid base58 payload data length for legacy address.
     */
    InvalidBase58PayloadLength = 29,
    /**
     * Invalid legacy address prefix in base58 data payload.
     */
    InvalidLegacyPrefix = 30,
    /**
     * Address's network differs from required one.
     */
    NetworkValidation = 31,
    /**
     * ------- Amount errors -------
     * The amount is too big or too small.
     */
    OutOfRange = 32,
    /**
     * Amount has higher precision than supported by the type.
     */
    TooPrecise = 33,
    /**
     * A digit was expected but not found.
     */
    MissingDigits = 34,
    /**
     * Input string was too large.
     */
    InputTooLarge = 35,
    /**
     * Invalid character in input.
     */
    InvalidCharacter = 36,
    /**
     * ------- Block application errors -------
     * Cannot connect block to the existing chain
     */
    CannotConnect = 37,
    /**
     * Connected-to hash does not match the expected hash
     */
    UnexpectedConnectedToHash = 38,
    /**
     * ------- Other errors -------
     * Unexpected error, should never happen
     */
    Unexpected = 39,
}

/**
 * A full Bitcoin block (header + transactions).
 *
 * Construct from consensus-encoded bytes using `Block.from_bytes()`.
 */
export class Block {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    /**
     * Deserialize a block from consensus-encoded bytes.
     *
     * Accepts a `Uint8Array` of raw block bytes as produced by Bitcoin Core
     * or any standard Bitcoin serializer.
     */
    static from_bytes(bytes: Uint8Array): Block;
    /**
     * Returns the block hash.
     */
    readonly block_hash: string;
    /**
     * Returns the previous block hash from the header.
     */
    readonly prev_blockhash: string;
    /**
     * Returns the block header timestamp.
     */
    readonly time: number;
    /**
     * Returns the number of transactions in the block.
     */
    readonly tx_count: number;
    /**
     * Returns the list of transactions in the block.
     */
    readonly txdata: Transaction[];
}

/**
 * A reference to a block in the canonical chain.
 */
export class BlockId {
    free(): void;
    [Symbol.dispose](): void;
    /**
     * Create a new `BlockId` from a height and block hash string.
     */
    constructor(height: number, hash: string);
    /**
     * The hash of the block.
     */
    readonly hash: string;
    /**
     * The height of the block.
     */
    readonly height: number;
}

/**
 * Represents the observed position of some chain data.
 */
export class ChainPosition {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    /**
     * The [`Anchor`].
     */
    readonly anchor: ConfirmationBlockTime | undefined;
    /**
     * Determines the upper bound of the confirmation height.
     */
    readonly confirmation_height_upper_bound: number | undefined;
    /**
     * When the chain data was first seen in the mempool.
     *
     * This value will be `None` if the chain data was never seen in the mempool.
     */
    readonly first_seen: bigint | undefined;
    /**
     * Returns whether [`ChainPosition`] is confirmed or not.
     */
    readonly is_confirmed: boolean;
    /**
     * When the chain data is last seen in the mempool.
     *
     * This value will be `None` if the chain data was never seen in the mempool and only seen
     * in a conflicting chain.
     */
    readonly last_seen: bigint | undefined;
    /**
     * Whether the chain data is anchored transitively by a child transaction.
     *
     * If the value is `Some`, it means we have incomplete data. We can only deduce that the
     * chain data is confirmed at a block equal to or lower than the block referenced by `A`.
     */
    readonly transitively: Txid | undefined;
}

/**
 * A changeset for [`Wallet`].
 */
export class ChangeSet {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    /**
     * Create a new `ChangeSet` from a JSON string.
     */
    static from_json(val: string): ChangeSet;
    is_empty(): boolean;
    /**
     * Merge another [`ChangeSet`] into itself.
     *
     * Conflicting non-empty descriptors or networks return an error without modifying
     * the destination. Missing identity fields are allowed in incremental changesets;
     * callers remain responsible for ensuring those changes belong to the same wallet.
     */
    merge(other: ChangeSet): void;
    /**
     * Serialize `ChangeSet` to JSON.
     */
    to_json(): string;
}

/**
 * Policy regarding the use of change outputs when creating a transaction.
 */
export enum ChangeSpendPolicy {
    /**
     * Use both change and non-change outputs (default)
     */
    ChangeAllowed = 0,
    /**
     * Only use change outputs
     */
    OnlyChange = 1,
    /**
     * Do not use any change outputs
     */
    ChangeForbidden = 2,
}

/**
 * A checkpoint is a node of a reference-counted linked list of [`BlockId`]s.
 *
 * Checkpoints are cheaply cloneable and are useful to find the agreement point between two sparse
 * block chains.
 */
export class CheckPoint {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    /**
     * Get checkpoint at `height`.
     *
     * Returns `None` if checkpoint at `height` does not exist.
     */
    get(height: number): CheckPoint | undefined;
    /**
     * Get the [`BlockId`] of the checkpoint.
     */
    readonly block_id: BlockId;
    /**
     * Get the block hash of the checkpoint.
     */
    readonly hash: string;
    /**
     * Get the height of the checkpoint.
     */
    readonly height: number;
    /**
     * Get the previous checkpoint in the chain
     */
    readonly prev: CheckPoint | undefined;
}

/**
 * CSV / CLTV requirements for transaction construction.
 *
 * Prefer `Policy.get_condition()` when selecting a descriptor spending path.
 */
export class Condition {
    free(): void;
    [Symbol.dispose](): void;
    /**
     * Combine requirements from every keychain whose inputs may be selected.
     *
     * Returns a new condition with the stricter requirements; neither input is
     * changed or consumed. Mixing height and time units returns an error.
     */
    merge(other: Condition): Condition;
    /**
     * Construct known requirements directly, or omit both for an immediate path.
     *
     * `csv` is a consensus nSequence value: blocks, or bit 22 plus units of 512
     * seconds. The disable flag is rejected and unused BIP68 bits are cleared.
     * `timelock` is consensus nLockTime:
     * heights below 500,000,000, Unix seconds otherwise. Both must be unsigned
     * 32-bit integers. These values are not checked against a descriptor.
     */
    constructor(csv?: number | null, timelock?: number | null);
    /**
     * Optional consensus nSequence requirement.
     */
    readonly csv: number | undefined;
    /**
     * Optional consensus nLockTime requirement.
     */
    readonly timelock: number | undefined;
}

/**
 * Represents the observed position of some chain data.
 */
export class ConfirmationBlockTime {
    private constructor();
    free(): void;
    [Symbol.dispose](): void;
    /**
     * The anchor block.
     */
    readonly block_id: BlockId;
    /**
     * The confirmation time of the transaction being anchored.
     */
    readonly confirmation_time: bigint;
}

